package org.jlinalg.cli;
import static org.junit.jupiter.api.Assertions.*;
import java.io.IOException;
import java.nio.file.*;
import java.util.Map;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;
import org.junit.jupiter.api.Assumptions;
class ScviRuntimeTest {
    @TempDir Path root;
    @Test void completeRuntimeTreeDetectsSourceChangesAndExtraEmptyDirectories()throws Exception{Path p=Files.createDirectory(root.resolve("provider"));Files.writeString(p.resolve("module.py"),"x=1\n");var a=ScviRuntime.tree(p,ScviRuntime.Limits.health(),()->{});assertEquals(2,a.members().size());Files.writeString(p.resolve("module.py"),"x=2\n");assertNotEquals(a,ScviRuntime.tree(p,ScviRuntime.Limits.health(),()->{}));Files.writeString(p.resolve("module.py"),"x=1\n");assertEquals(a,ScviRuntime.tree(p,ScviRuntime.Limits.health(),()->{}));Files.createDirectory(p.resolve("extra"));assertNotEquals(a,ScviRuntime.tree(p,ScviRuntime.Limits.health(),()->{}));}
    @Test void runtimeFingerprintHasByteMemberAndRetainedMemoryBounds()throws Exception{Path p=Files.createDirectory(root.resolve("provider"));Files.writeString(p.resolve("module.py"),"abcdef");for(ScviRuntime.Limits l:new ScviRuntime.Limits[]{new ScviRuntime.Limits(5,10,100000,1024,ScviProcess.Limits.health()),new ScviRuntime.Limits(1000,1,100000,1024,ScviProcess.Limits.health()),new ScviRuntime.Limits(1000,10,1,1024,ScviProcess.Limits.health())})assertThrows(IOException.class,()->ScviRuntime.tree(p,l,()->{}));}
    @Test void exactHistoricalProfilesAreUnavailableBeforeAnyLaunchOrOutput()throws Exception{for(var release:new ScviModelRequest.Release[]{ScviModelRequest.Release.V1_0_3,ScviModelRequest.Release.V1_2_0}){Path out=root.resolve("new-"+release);var error=assertThrows(ScviRuntime.Unavailable.class,()->ScviRuntime.admit(root.resolve("missing-python"),release,out,ScviRuntime.Limits.health(),()->{}));assertTrue(error.getMessage().contains("no version is substituted"));assertFalse(Files.exists(out));}}
    @Test void missingOrForbiddenProviderHasRecoveryAndCreatesNoAdmission()throws Exception{Path out=root.resolve("unavailable");var e=assertThrows(ScviRuntime.Unavailable.class,()->ScviRuntime.admit(root.resolve("missing-python"),ScviModelRequest.Release.V1_3_0,out,ScviRuntime.Limits.health(),()->{}));assertTrue(e.getMessage().contains("Required action"));assertFalse(Files.exists(out));}
    @Test void controlledEnvironmentDoesNotInheritPythonOrLoaderInjection()throws Exception{Map<String,String> env=ScviRuntime.environment();assertFalse(env.containsKey("PYTHONPATH"));assertFalse(env.containsKey("LD_PRELOAD"));assertEquals("1",env.get("OPENBLAS_NUM_THREADS"));assertEquals("",env.get("CUDA_VISIBLE_DEVICES"));assertThrows(UnsupportedOperationException.class,()->env.put("PYTHONPATH","bad"));}
    @Test void fileLinksPinTheirTextTargetAndResolvedBytes()throws Exception{Path p=Files.createDirectory(root.resolve("provider")),target=root.resolve("python-real");Files.writeString(target,"original executable bytes");try{Files.createSymbolicLink(p.resolve("python"),target);}catch(IOException|UnsupportedOperationException|SecurityException unavailable){Assumptions.assumeTrue(false,"Symbolic link creation unavailable");}var a=ScviRuntime.tree(p,ScviRuntime.Limits.health(),()->{});assertEquals("file-link",a.members().get("python").kind());Files.writeString(target,"changed executable bytes");assertNotEquals(a,ScviRuntime.tree(p,ScviRuntime.Limits.health(),()->{}));}
    @Test void externalDirectoryLinksAreNeverSilentlyOmittedFromTheClosure()throws Exception{Path p=Files.createDirectory(root.resolve("provider")),target=Files.createDirectory(root.resolve("external"));try{Files.createSymbolicLink(p.resolve("external"),target);}catch(IOException|UnsupportedOperationException|SecurityException unavailable){Assumptions.assumeTrue(false,"Symbolic link creation unavailable");}assertThrows(IOException.class,()->ScviRuntime.tree(p,ScviRuntime.Limits.health(),()->{}));}
}
